import unittest
from candidate import remove_vowels

class TestRemoveVowels(unittest.TestCase):
    def test_remove_vowels_empty_string(self):
        self.assertEqual(remove_vowels(''), '')

    def test_remove_vowels_normal_lowercase(self):
        self.assertEqual(remove_vowels('abcdef'), 'bcdf')

    def test_remove_vowels_with_newline(self):
        self.assertEqual(remove_vowels("abcdef\nghijklm"), 'bcdf\nghjklm')

    def test_remove_vowels_all_vowels(self):
        self.assertEqual(remove_vowels('aaaaa'), '')

    def test_remove_vowels_mixed_case(self):
        self.assertEqual(remove_vowels('aaBAA'), 'B')

    def test_remove_vowels_no_vowels(self):
        self.assertEqual(remove_vowels('zbcd'), 'zbcd')

    def test_remove_vowels_single_consonant(self):
        self.assertEqual(remove_vowels('z'), 'z')

    def test_remove_vowels_uppercase_consonant_kept(self):
        self.assertEqual(remove_vowels('BCDF'), 'BCDF')

    def test_remove_vowels_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            remove_vowels(None)

    def test_remove_vowels_integer_raises_type_error(self):
        with self.assertRaises(TypeError):
            remove_vowels(123)
